public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    int n = strings.size();
    // Determine the shortest string length to limit substring length
    int minLen = strings.get(0).length();
    for (int i = 1; i < n; i++) {
        int len = strings.get(i).length();
        if (len < minLen) {
            minLen = len;
        }
    }
    String reference = strings.get(0);
    // Try lengths from longest possible down to 1
    for (int len = minLen; len >= 1; len--) {
        // Gather all substrings of this length from the reference string
        Set<String> candidates = new java.util.HashSet<>();
        for (int start = 0; start <= reference.length() - len; start++) {
            candidates.add(reference.substring(start, start + len));
        }
        // Check each candidate against all strings
        for (String cand : candidates) {
            String rev = new StringBuilder(cand).reverse().toString();
            boolean valid = true;
            for (int i = 0; i < n; i++) {
                String s = strings.get(i);
                if (!(s.contains(cand) || s.contains(rev))) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                return len;
            }
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) return 0;
    int rows = grid.length;
    int cols = grid[0].length;
    int count = 0;
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1,  0,  1,-1, 1,-1, 0, 1};

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@') {
                count++;
                // DFS/BFS to mark all connected '@'
                java.util.Deque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                grid[r][c] = '*';
                while (!stack.isEmpty()) {
                    int[] cell = stack.pop();
                    int cr = cell[0], cc = cell[1];
                    for (int k = 0; k < 8; k++) {
                        int nr = cr + dr[k];
                        int nc = cc + dc[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '@') {
                            grid[nr][nc] = '*';
