public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0) return false;
    int[] modCount = new int[k];
    for (int num : arr) {
        int r = Math.floorMod(num, k);
        modCount[r]++;
    }

    // Remainder 0 must have even count
    if (modCount[0] % 2 != 0) return false;

    // If k is even, remainder k/2 must also have even count
    if (k % 2 == 0 && modCount[k / 2] % 2 != 0) return false;

    // For other remainders, counts must pair up
    for (int i = 1; i <= k / 2; i++) {
        if (i == k - i) { // already handled k even case
            continue;
        }
        if (modCount[i] != modCount[k - i]) {
            return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Build adjacency list
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        graph[u].add(v);
        graph[v].add(u);
    }

    // Determine parent relation and traversal order using DFS stack
    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -1);
    int[] order = new int[n];
    int idx = 0;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    stack.push(0);
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order[idx++] = node;
        for (int nei : graph[node]) {
            if (nei != parent[node]) {
                parent[nei] = node;
                stack.push(nei);
            }
        }
    }

    // Bottom-up computation of time required for each subtree
    int[] time = new int[n];
    boolean[] needed = new boolean[n];
    for (int i = n - 1; i >= 0; i--) {
        int node = order[i];
        needed[node] = hasApple[node];
        for (int nei : graph[node]) {
            if (parent[nei] == node && needed[nei]) {
                needed[node] = true;
                time[node] += time[nei] + 2;
            }
        }
    }
    return time[0];
}

public String sortString(String s) {
    int[] cnt = new int[26];
    for (char c : s.toCharArray()) {
        cnt[c - 'a']++;
    }
    StringBuilder sb = new StringBuilder();
    int remaining = s.length();
    while (remaining > 0) {
        // Ascending part: pick smallest, then smallest greater than last
        int lastAsc = -1;
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (cnt[i] > 0 && (lastAsc == -1 || i > lastAsc)) {
                sb.append((char) ('a' + i));
                cnt[i]--;
                remaining--;
                lastAsc = i;
            }
        }
        // Descending part: pick largest, then largest smaller than last
        int lastDesc = 26;
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (cnt[i] > 0 && i < lastDesc) {
                sb.append((char) ('a' + i));
                cnt[i]--;
                remaining--;
                lastDesc = i;
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int total = 0;
    for (int num : nums) total += num;
    int maxK = n / 2;
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[maxK + 1];
    for (int i = 0; i <= maxK; i++) dp[i] = new java.util.HashSet<>();
    dp[0].add(0);
    for (int num : nums) {
        for (int k = maxK; k >= 1; k--) {
            for (int s : dp[k - 1]) {
                dp[k].add(s + num);
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        if ((total * k) % n != 0) continue;
        int target = (total * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

