public int minInsertions(String s) {
    int balance = 0;      // number of unmatched '('
    int insertions = 0;   // number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance == 0) {
                // Need an opening bracket before this ')'
                insertions++;
            } else {
                balance--;   // match with a previous '('
            }
        }
    }
    // All remaining unmatched '(' need closing brackets
    insertions += balance;
    return insertions;
}

