public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) return 0;
    int m = mat.length, n = mat[0].length;
    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] ad = new int[m][n];
    int max = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                vert[i][j]  = (i > 0 ? vert[i - 1][j] : 0) + 1;
                diag[i][j]  = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                ad[i][j]    = (i > 0 && j < n - 1 ? ad[i - 1][j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                        Math.max(diag[i][j], ad[i][j]));
                if (localMax > max) max = localMax;
            } else {
                horiz[i][j] = vert[i][j] = diag[i][j] = ad[i][j] = 0;
            }
        }
    }
    return max;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    int absValue = Math.abs(n);
    String s = Integer.toString(absValue);
    int len = s.length();
    StringBuilder result = new StringBuilder();
    int firstGroupLen = len % 3;
    if (firstGroupLen == 0) {
        firstGroupLen = 3;
    }
    result.append(s, 0, firstGroupLen);
    for (int i = firstGroupLen; i < len; i += 3) {
        result.append('.');
        result.append(s, i, i + 3);
    }
    if (negative) {
        result.insert(0, '-');
    }
    return result.toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    int[] arr = A.clone();
    Arrays.sort(arr);
    // Precompute perfect squares up to 2*max
    int maxVal = arr[n - 1];
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 1; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    // Build adjacency list
    List<Integer>[] adj = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new ArrayList<>();
        for (int j = 0; j < n; j++) {
            if (i != j && isSquare[arr[i] + arr[j]]) {
                adj[i].add(j);
            }
        }
    }
    boolean[] used = new boolean[n];
    int[] count = new int[1];

    // DFS
    void dfs(int pos, int lastIdx) {
        if (pos == n) {
            count[0]++;
            return;
        }
        for (int i = 0; i < n; i++) {
            if (used[i]) continue;
            // skip duplicates
            if (i > 0 && arr[i] == arr[i - 1] && !used[i - 1]) continue;
            if (lastIdx == -1) {
                used[i] = true;
                dfs(pos + 1, i);
                used[i] = false;
            } else {
                // check adjacency
                if (isSquare[arr[lastIdx] + arr[i]]) {
                    used[i] = true;
                    dfs(pos + 1, i);
                    used[i] = false;
                }
            }
        }
    }

    dfs(0, -1);
    return count[0];
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = 0;
    stack[top++] = -1; // sentinel for index before the start
    int maxArea = 0;

    for (int i = 0; i < n; i++) {
        while (top > 1 && heights[stack[top - 1]] >= heights[i]) {
            int height = heights[stack[--top]];
            int width = i - stack[top - 1] - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[top++] = i;
    }

    while (top > 1) {
        int height = heights[stack[--top]];
        int width = n - stack[top - 1] - 1;
        int area = height * width;
        if (area > maxArea) {
            maxArea = area;
        }
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    for (int sum = 0; sum < m + n - 1; sum++) {
        if (sum % 2 == 0) { // even sums go from bottom to top
            int row = Math.min(sum, m - 1);
            int col = sum - row;
            while (row >= 0 && col < n) {
                result[index++] = mat[row][col];
                row--;
                col++;
            }
        } else { // odd sums go from top to bottom
            int col = Math.min(sum, n - 1);
            int row = sum - col;
            while (col >= 0 && row < m) {
                result[index++] = mat[row][col];
                row++;
                col--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    String s = Integer.toString(n);
    int len = s.length();
    int[] digits = new int[len];
    for (int i = 0; i < len; i++) {
        digits[i] = s.charAt(i) - '0';
    }

    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    if (i < 0) {
        return -1;
    }

    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    int temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    int left = i + 1, right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    int result = 0;
    for (int d : digits) {
        result = result * 10 + d;
    }

    return result > n ? result : -1;
}

