public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int[] p1 = points[0];
    int[] p2 = points[1];
    int[] p3 = points[2];

    // Ensure all points are distinct
    if ((p1[0] == p2[0] && p1[1] == p2[1]) ||
        (p1[0] == p3[0] && p1[1] == p3[1]) ||
        (p2[0] == p3[0] && p2[1] == p3[1])) {
        return false;
    }

    // Compute twice the signed area of the triangle
    int area = (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p3[0] - p1[0]) * (p2[1] - p1[1]);

    // Non-zero area means the points are not collinear
    return area != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) return 0;
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxEnergy = 1;
    int currentEnergy = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
        } else {
            if (currentEnergy > maxEnergy) {
                maxEnergy = currentEnergy;
            }
            currentEnergy = 1;
        }
    }
    return Math.max(maxEnergy, currentEnergy);
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    int curr = 1;
    for (int i = 0; i < n; i++) {
        result.add(curr);
        if (curr * 10 <= n) {
            curr *= 10;
        } else {
            if (curr % 10 != 9 && curr + 1 <= n) {
                curr += 1;
            } else {
                while (((curr / 10) % 10 == 9) || (curr + 1 > n)) {
                    curr /= 10;
                }
                curr += 1;
            }
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < min) {
                min = dp[i - square] + 1;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        result.append(new StringBuilder(words[i]).reverse());
        if (i < words.length - 1) {
            result.append(' ');
        }
    }
    return result.toString();
}
